#!/usr/bin/env python3
"""Generate the typed Sway frontend from Weld-owned grammar definitions."""

import json
import re
import subprocess
import sys
from typing import Annotated

import typer

from dev.cli import command
from dev.paths import ROOT

SCHEMA = ROOT / "tools/config-codegen/sway.json"
DESTINATION = ROOT / "crates/weld-sway-config/src/typed/generated.rs"
INVENTORY = ROOT / "tools/config-codegen/coverage.json"
MAPPINGS = ROOT / "crates/weld-sway-config/src/lowering/keys.rs"


def generate(schema):
    lines = [
        "// Generated by uv run generate-config; edit sway.json.",
        "use super::*;",
    ]
    enums = dict(schema["enums"])
    for definition in schema.get("streams", {}).values():
        if definition["kind"] in enums:
            raise ValueError("stream kinds must have a single definition")
        enums[definition["kind"]] = {
            name: item["aliases"] for name, item in definition["items"].items()
        }
    known = set(enums) | set(schema["scalars"]) | set(schema["productions"])
    known |= {
        "WorkspaceTarget",
        "RenameWorkspace",
        "ShellCommand",
        "Layout",
        "Persistence",
        "Resize",
        "Position",
        "FiniteFloat",
        "Literal",
        "Literals",
        "PositiveInteger",
        "Modifiers",
        "Colors",
        "FontDescription",
        "WorkspaceAssignment",
        "XkbValue",
    }
    for name, definition in schema.get("structs", {}).items():
        lines += [
            f"/// {definition['description']}",
            "#[derive(Clone, Debug, PartialEq)]",
            f"pub struct {name} {{",
        ]
        for field, declaration in definition["fields"].items():
            lines += [
                f"/// {declaration['description']}",
                f"pub {field}: {declaration['type']},",
            ]
        lines += ["}"]
    for name, definition in schema["scalars"].items():
        kind = definition["kind"]
        rust_type = "String" if kind == "string" else kind
        lines += [
            f"/// Validated {name} configuration value.",
            "#[derive(Clone, Debug, Eq, PartialEq, Hash)]",
            f"pub struct {name}({rust_type});",
            f"impl {name} {{",
            "/// Construct a value after checking its local invariants.",
            f"pub fn new(value: {rust_type}) -> Result<Self> {{",
        ]
        if kind == "string":
            lines += [f'ensure!(!value.is_empty(), "{name} must not be empty");']
        else:
            lines += [
                f'ensure!(({definition["min"]}..={definition["max"]}).contains(&value), "{name} is outside its allowed range");'
            ]
        lines += ["Ok(Self(value))", "}", "/// The validated value."]
        if kind == "string":
            lines += [
                "pub fn as_str(&self) -> &str { &self.0 }",
                "/// Take ownership of the decoded text.",
                "pub fn into_string(self) -> String { self.0 }",
            ]
            parse = "Self::new(literal(word)?.to_owned())"
        else:
            lines += [f"pub fn value(&self) -> {rust_type} {{ self.0 }}"]
            parse = "Self::new(word.parse()?)"
        lines += [
            "}",
            f"impl Word for {name} {{ fn word(word: &str) -> Result<Self> {{ {parse} }} }}",
        ]
    for name, variants in enums.items():
        lines += [
            f"/// Alternatives in the {name} syntax.",
            "#[derive(Clone, Copy, Debug, Eq, PartialEq, Hash)]",
            f"pub enum {name} {{",
        ]
        seen = set()
        for variant, aliases in variants.items():
            if seen.intersection(aliases):
                raise ValueError(f"duplicate spelling in {name}")
            seen.update(aliases)
            lines += [f"/// Accepted spellings: {', '.join(aliases)}.", f"{variant},"]
        lines += [
            "}",
            f"impl Word for {name} {{ fn word(word: &str) -> Result<Self> {{ Ok(match word {{",
        ]
        for variant, aliases in variants.items():
            lines += [
                " | ".join(json.dumps(alias) for alias in aliases)
                + f" => Self::{variant},"
            ]
        for value in schema.get("unsupported_values", {}).get(name, []):
            if value in seen:
                raise ValueError(
                    f"{name} marks an accepted spelling unsupported: {value}"
                )
            lines += [
                f'{json.dumps(value)} => return Err(unsupported(format!("unsupported {name} {{word}}"))),'
            ]
        if name in schema.get("unsupported_enums", []):
            lines += [
                f'_ => return Err(unsupported(format!("unsupported {name} {{word}}"))),'
            ]
        else:
            lines += [f'_ => bail!("invalid {name}: {{word}}"),']
        lines += ["}) } }"]
    for name, definition in schema["productions"].items():
        lines += [
            f"/// Typed {name} production.",
            "#[derive(Clone, Debug, PartialEq)]",
            f"pub enum {name} {{",
        ]
        for variant, fields in definition["variants"].items():
            lines += [
                f"/// The {variant} form.",
                f"{variant}" + (f"({fields})" if fields else "") + ",",
            ]
        lines += [
            "}",
            f"impl Words for {name} {{ fn words(words: &[&str]) -> Result<Self> {{ Ok(match words {{",
        ]
        patterns = set()
        for rule in definition["rules"]:
            pattern, bindings = [], []
            for index, token in enumerate(rule["pattern"]):
                if not token.startswith("$"):
                    pattern.append(json.dumps(token))
                    continue
                field, kind = token[1:].split(":")
                rest = kind.endswith("*")
                kind = kind.rstrip("*")
                if kind not in known or not re.fullmatch(r"[a-z][a-z_]*", field):
                    raise ValueError(f"invalid capture {token}")
                if rest and index != len(rule["pattern"]) - 1:
                    raise ValueError("tail captures must be last")
                pattern.append(f"{field} @ .." if rest else field)
                bindings.append(
                    f"let {field} = {kind}::{'words' if rest else 'word'}({field})?;"
                )
            pattern = "[" + ", ".join(pattern) + "]"
            if pattern in patterns:
                raise ValueError(f"duplicate production {name}: {pattern}")
            patterns.add(pattern)
            if not rule["value"].startswith("Self::"):
                raise ValueError("production must construct its declared syntax type")
            lines += [pattern + " => {", *bindings, rule["value"], "},"]
        if definition.get("fallback") == "invalid":
            lines += [f'_ => bail!("invalid {name}: {{}}", words.join(" ")),']
        else:
            for head in definition.get("invalid_heads", []):
                lines += [
                    f'[{json.dumps(head)}, ..] => bail!("invalid {name}: {{}}", words.join(" ")),'
                ]
            lines += [
                f'_ => return Err(unsupported(format!("unsupported {name}: {{}}", words.join(" ")))),'
            ]
        lines += ["}) } }"]
    for name, definition in schema.get("streams", {}).items():
        kind = definition["kind"]
        supported = {
            variant: item
            for variant, item in definition["items"].items()
            if "value" in item
        }
        lines += [
            f"/// Parsed {name} with unsupported arguments consumed according to the grammar.",
            "#[derive(Clone, Debug, PartialEq)]",
            f"pub enum {name} {{",
        ]
        for variant, item in supported.items():
            if item["value"] not in known:
                raise ValueError(f"unknown stream value type {item['value']}")
            lines += [f"/// The {variant} property.", f"{variant}({item['value']}),"]
        lines += [
            "/// A recognized property whose execution is not implemented.",
            f"Skipped({kind}),",
            "}",
            f"impl {kind} {{",
            "/// Whether the property currently produces a supported typed value.",
            "pub(crate) fn is_supported(self) -> bool { match self {",
        ]
        for variant in definition["items"]:
            lines += [f"Self::{variant} => {str(variant in supported).lower()},"]
        lines += [
            "} }",
            "/// Consume exactly one property from a chained directive.",
            f"pub(crate) fn parse_next<'a>(self, words: &mut std::iter::Peekable<impl Iterator<Item = &'a str>>) -> Result<{name}> {{",
            "Ok(match self {",
        ]
        for variant, item in definition["items"].items():
            lines += [f"Self::{variant} => {{"]
            context = json.dumps(f"output {item['aliases'][0]} requires an argument")
            if "value" in item:
                if "consume" in item:
                    raise ValueError(
                        "stream values and skip grammars are mutually exclusive"
                    )
                lines += [
                    f"{name}::{variant}({item['value']}::word(words.next().context({context})?)?)"
                ]
            else:
                consume = item["consume"]
                if set(consume) <= {"count", "optional_prefix"} and "count" in consume:
                    if type(consume["count"]) is not int or consume["count"] < 0:
                        raise ValueError(
                            "stream argument counts must be nonnegative integers"
                        )
                    if "optional_prefix" in consume:
                        lines += [
                            f"if words.peek() == Some(&{json.dumps(consume['optional_prefix'])}) {{ words.next(); }}"
                        ]
                    for _ in range(consume["count"]):
                        lines += [f"words.next().context({context})?;"]
                elif set(consume) == {"pair_separator"} and consume["pair_separator"]:
                    lines += [
                        f"let first = words.next().context({context})?;",
                        f"if !first.contains({json.dumps(consume['pair_separator'])}) {{ words.next().context({context})?; }}",
                    ]
                else:
                    raise ValueError("invalid stream argument grammar")
                lines += [f"{name}::Skipped(self)"]
            lines += ["},"]
        lines += ["}) } }"]
    return "\n".join(lines) + "\n"


def coverage(schema):
    imported = json.loads((ROOT / "tools/config-codegen/i3.json").read_text())
    consumers = {state: [] for state in imported["states"]}
    for owner, states in schema["references"].items():
        for state in states:
            if state not in consumers:
                raise ValueError(f"unknown upstream state {state} for {owner}")
            consumers[state].append(owner)
    return {
        "revision": imported["revision"],
        "note": "Adapted states may cover only Weld's existing subset; reference-only states add no executable support.",
        "states": [
            {
                "state": state,
                "line": definition["line"],
                "disposition": "adapted" if consumers[state] else "reference-only",
                "owners": consumers[state],
                "callbacks": sorted(
                    {
                        callback
                        for production in definition["productions"]
                        for callback in production["callbacks"]
                    }
                ),
            }
            for state, definition in imported["states"].items()
        ],
    }


def mappings(schema):
    mapping = schema["physical_keys"]
    if set(mapping) != set(schema["enums"]["Key"]):
        raise ValueError("every supported key requires exactly one physical identity")
    if any(not isinstance(code, int) or code <= 0 for code in mapping.values()):
        raise ValueError("physical key identities must be positive evdev codes")
    return (
        "\n".join(
            [
                "// Generated by uv run generate-config; edit sway.json.",
                "use crate::typed::Key;",
                "pub(super) fn key(value: Key) -> u32 { match value {",
                *[f"Key::{variant} => {code}," for variant, code in mapping.items()],
                "} }",
            ]
        )
        + "\n"
    )


def main(check: Annotated[bool, typer.Option("--check")] = False):
    schema = json.loads(SCHEMA.read_text())
    source = generate(schema)
    outputs = {}
    for destination, rust in [(DESTINATION, source), (MAPPINGS, mappings(schema))]:
        outputs[destination] = subprocess.run(
            ["rustfmt", "--edition", "2024", "--emit", "stdout"],
            input=rust,
            text=True,
            capture_output=True,
            check=True,
        ).stdout
    outputs[INVENTORY] = json.dumps(coverage(schema), indent=2) + "\n"
    for destination, output in outputs.items():
        if check:
            if not destination.exists() or destination.read_text() != output:
                print(f"stale generated file: {destination}", file=sys.stderr)
                raise typer.Exit(1)
        else:
            destination.write_text(output)
    return 0


app = command(main, help=__doc__)

if __name__ == "__main__":
    app()
